<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Referrals</title><style>body{font-family:Arial;background:#f5f7fb;margin:0;color:#1f2937}.wrap{max-width:1250px;margin:auto;padding:25px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin-top:18px}input,select,button,.btn{padding:9px;border-radius:7px;border:1px solid #d0d5dd}.btn,button{background:#111827;color:#fff;text-decoration:none}.primary{background:#2563eb}table{width:100%;border-collapse:collapse;margin-top:15px}th,td{padding:9px;border-bottom:1px solid #eee;text-align:left}.muted{color:#667085}.status{font-weight:600}</style></head><body><div class="wrap"><h1>Student Referrals</h1><div class="muted">Referrer: {{$parent->student_name}} ({{$parent->student_no}}) · Current Point: {{$parent->student_point}}</div><div class="card"><form method="GET"><input name="search" placeholder="Name, ID, phone, WhatsApp, email" value="{{request('search')}}"><select name="status"><option value="">All Status</option><option value="1" @selected(request('status')==='1')>Active</option><option value="0" @selected(request('status')==='0')>Pending</option><option value="2" @selected(request('status')==='2')>Blocked</option></select><input type="date" name="from" value="{{request('from')}}"><input type="date" name="to" value="{{request('to')}}"><button class="primary">Filter</button> <a class="btn" href="{{route('admin.students.index')}}">Students</a></form><table><thead><tr><th>Student ID</th><th>Name</th><th>WhatsApp</th><th>Point</th><th>Status</th><th>Trainer</th><th>Registered</th><th>Action</th></tr></thead><tbody>@forelse($students as $s)<tr><td>{{$s->student_no}}</td><td>{{$s->student_name}}</td><td>{{$s->student_whatsapp}}</td><td>{{$s->student_point}}</td><td class="status">{{(int)$s->student_status===1?'Active':((int)$s->student_status===2?'Blocked':'Pending')}}</td><td>{{trim(($s->trainer_firstname??'').' '.($s->trainer_lastname??''))}}</td><td>{{$s->created_at}}</td><td><a class="btn primary" href="{{route('admin.students.edit',$s->id)}}">View/Edit</a><a class="btn" href="{{route('admin.students.referrals',$s->id)}}" style="margin-left:4px">Referrals</a></td></tr>@empty<tr><td colspan="8">No referred students found.</td></tr>@endforelse</tbody></table>{{$students->links()}}</div></div></body></html>